import{_ as a,a as e,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"肌肉力量训练 彩色图谱","description":"围绕肌肉功能、基本动作和训练安排阅读力量训练图谱，区分解剖示意与个体动作方案。","frontmatter":{"title":"肌肉力量训练 彩色图谱","description":"围绕肌肉功能、基本动作和训练安排阅读力量训练图谱，区分解剖示意与个体动作方案。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 个人成长、心理学与健康生活 · 运动与健康","summary":"围绕肌肉功能、基本动作和训练安排阅读力量训练图谱，区分解剖示意与个体动作方案。","status":"active","related":[{"title":"精准拉伸","link":"/life/personal/books/growth/stretching","kind":"书籍导读","scope":"general","audience":"general"},{"title":"从零开始学游泳","link":"/life/personal/books/growth/swimming","kind":"书籍导读","scope":"general","audience":"general"}],"prev":false,"next":{"text":"精准拉伸","link":"/life/personal/books/growth/stretching"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"精准拉伸","link":"/life/personal/books/growth/stretching"}},"headers":[],"relativePath":"life/personal/books/growth/strength-training.md","filePath":"life/personal/books/growth/strength-training.md"}'),n={name:"life/personal/books/growth/strength-training.md"};function i(l,t,s,d,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="肌肉力量训练-彩色图谱" tabindex="-1">肌肉力量训练 彩色图谱 <a class="header-anchor" href="#肌肉力量训练-彩色图谱" aria-label="Permalink to &quot;肌肉力量训练 彩色图谱&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p><strong>分类：个人成长、心理学与健康生活 → 运动与健康。</strong> 图谱类训练书通过解剖插图与动作说明，帮助读者理解动作涉及的肌群、关节活动和发力方式。适合将“动作怎么做”与“身体为什么这样动”联系起来阅读。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《肌肉力量训练彩色图谱》：可核书目作者为里卡多·卡诺瓦斯·里内拉斯（Ricardo Cánovas Lineras）。</strong> <a href="https://detail.youzan.com/show/goods?alias=26u2iqm8s5v1t&amp;from_source=gbox_seo" target="_blank" rel="noopener noreferrer">人民邮电出版社官方店铺</a>列出2015年第1版、ISBN 9787115392206，并介绍其医学与外科学位和运动医学、教学背景。履历来自出版方介绍，本页未独立审查任职现状；专业背景不使示范自动适用于所有个体。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合想认识肌群、读懂力量训练动作说明的普通健身读者，也可用作与教练交流时的术语参考。本页只评析图书阅读价值，无法据图谱替个体制定训练或伤后恢复方案。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>已核到人民邮电出版社2015年第1版、ISBN 9787115392206；用户所持ISBN仍需对照。下表保留本站主题导读，不是原书逐项目录。出版社目录按胸、背、肩、手臂、腿、臀、腹及训练计划组织，动作细节需回查对应页。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题导读</th><th>主要内容</th><th>阅读时要检查</th></tr></thead><tbody><tr><td>解剖与动作语言</td><td>认识主要肌群、关节运动方向及身体姿态。</td><td>插图中的肌肉标色表示什么，是否把参与误解为孤立发力。</td></tr><tr><td>上肢推拉</td><td>理解胸、背、肩、手臂在推举和拉动中的配合。</td><td>肩胛与躯干是否稳定，动作幅度是否适合当前能力。</td></tr><tr><td>下肢与髋部</td><td>从蹲、髋屈伸和单腿动作理解腿部与臀部的作用。</td><td>是否只关注负重，忽略平衡与动作控制。</td></tr><tr><td>躯干稳定</td><td>观察呼吸、躯干位置与四肢动作之间的联系。</td><td>是否把核心训练等同于反复卷腹。</td></tr><tr><td>训练安排</td><td>将动作、组次、负荷、间歇和频率放进完整计划。</td><td>计划是否有清楚目标，能否根据恢复情况调整。</td></tr><tr><td>进步与恢复</td><td>记录训练质量、负荷变化和疲劳感，逐步增加要求。</td><td>出现疼痛时是否及时停止相关动作并寻求评估。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析：</strong> 解剖图能解释动作，却不会自动提供适合每个人的训练方案。身体比例、活动能力、既往伤病和训练经验都会改变动作选择。阅读图谱时，值得建立的是观察动作的语言，而不是仅凭一张插图判断所有人的“标准姿势”。</p><p>把训练日志与书中的动作说明对照，可以逐步发现负荷、控制和恢复之间的关系。运动效果需要持续实践检验，图谱也不能替代疼痛或损伤的专业评估。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 看懂肌肉标色只是开始，还要读懂动作说明的条件和限制。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 为一个动作做阅读卡，记录目标部位、动作描述、常见错误和仍不懂的术语。比较同一部位不同动作的器械与身体位置，把不确定处整理成向教练提问的问题，而非只按插图安排训练。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>图文并列便于理解身体部位，但静态图难呈现动作全过程和个体差异，按肌群编排也容易让人只收集动作。<strong>推荐语：</strong> 适合作为动作语言与解剖常识参考书，将注意事项和错误提示与插图一起读。</p><h2 id="来源或核对入口" tabindex="-1">来源或核对入口 <a class="header-anchor" href="#来源或核对入口" aria-label="Permalink to &quot;来源或核对入口&quot;">​</a></h2><ul><li><a href="https://search.worldcat.org/search?q=%E8%82%8C%E8%82%89%E5%8A%9B%E9%87%8F%E8%AE%AD%E7%BB%83+%E5%BD%A9%E8%89%B2%E5%9B%BE%E8%B0%B1" target="_blank" rel="noopener noreferrer">WorldCat 题名检索</a>：核对作者、译者与版次，当前未确认目录。</li><li>阅读实物时优先核对动作说明中的适用条件、注意事项及解剖术语，避免只模仿图片外观。</li></ul><p><a href="./../overview">返回书单总览</a></p>',23)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
